  }
}
function enterOrbit() {
  sim.phase = 'settled'; const c = wreckCenter(tmpV);
  cam.orbitStart = sim.t; cam.orbitBase = Math.atan2(cam.pos.z - c.z, cam.pos.x - c.x); cam.orbitR = Math.hypot(cam.pos.x - c.x, cam.pos.z - c.z); cam.orbitH = cam.pos.y;
}

// ---------------------------------------------------------------- camera rig (auto cinematic, free orbit on drag)
const cam = { pos: V3(), tgt: V3(), dPos: V3(), dTgt: V3(), shake: 0, manual: false, orbitStart: 0, orbitBase: 0, orbitR: 13, orbitH: 3.8 };
const controls = new OrbitControls(camera, renderer.domElement);
controls.enabled = false; controls.enableDamping = true; controls.maxPolarAngle = Math.PI / 2 - 0.03; controls.minDistance = 3; controls.maxDistance = 90;
const takeManual = () => { if (cam.manual) return; cam.manual = true; controls.target.copy(cam.tgt); controls.enabled = true; };
renderer.domElement.addEventListener('pointerdown', takeManual, { capture: true });
renderer.domElement.addEventListener('wheel', takeManual, { capture: true, passive: true });
const wc = V3(), estPos = V3(), estTgt = V3(), crashPos = V3(), crashTgt = V3(), carTgt = V3(), midPos = V3(), dirEst = V3(0.25, 0.28, 1).normalize();
function computeDesired() {
  const cabT = sim.partByName.get('cabin').body.translation(), wallX = sim.wallX;
  const hfov = 2 * Math.atan(Math.tan(THREE.MathUtils.degToRad(camera.fov) / 2) * camera.aspect);
  crashPos.set(wallX - 9, 2.8, 10.5); crashTgt.set(wallX - 3.2, 0.9, 0.2);
  if (sim.phase === 'approach') {
    // establishing three-quarter shot framing car + track + wall, swooping along a bezier to the crash camera
    const midX = (cabT.x + wallX) / 2, halfSpan = (wallX - cabT.x) / 2 + 5.5, D = halfSpan / Math.tan(hfov / 2);
    estTgt.set(midX, 1.0, 0); estPos.copy(estTgt).addScaledVector(dirEst, D);
    midPos.set(wallX - 17, 5.0, 17);
    const p = smooth((cabT.x - sim.carX0) / (wallX - 9 - sim.carX0)), q = 1 - p;
    cam.dPos.set(0, 0, 0).addScaledVector(estPos, q * q).addScaledVector(midPos, 2 * q * p).addScaledVector(crashPos, p * p);
    carTgt.set(Math.min(cabT.x + 4.5, crashTgt.x), 0.75, 0);
    cam.dTgt.lerpVectors(estTgt, carTgt, smooth(p * 1.5));
  } else if (sim.phase === 'impact') {
    const since = sim.t - sim.impactT;
    wreckCenter(wc);
    cam.dTgt.lerpVectors(crashTgt, wc, smooth(since / 3));
    // hold the crash camera through the hit, then dolly alongside the wreck as it runs out past the wall
    tmpV.set(wc.x - 4.5, 3.0, 10.5);
    cam.dPos.lerpVectors(crashPos, tmpV, smooth((since - 1.0) / 3.5));
  } else {
    wreckCenter(wc);
    const since = sim.t - cam.orbitStart;
    cam.orbitR = lerp(cam.orbitR, 13, 0.01); cam.orbitH = lerp(cam.orbitH, 3.8, 0.01);
    const a = cam.orbitBase + since * 0.085;
    cam.dPos.set(wc.x + Math.cos(a) * cam.orbitR, cam.orbitH, wc.z + Math.sin(a) * cam.orbitR);
    cam.dTgt.copy(wc);
  }
}
function cameraReset() {
  cam.manual = false; controls.enabled = false; cam.shake = 0;
  computeDesired(); cam.pos.copy(cam.dPos); cam.tgt.copy(cam.dTgt);
  camera.position.copy(cam.pos); camera.lookAt(cam.tgt);
}

  hud.time.textContent = sim.t.toFixed(2) + ' s';
  hud.bodies.textContent = sim.world.bodies.len() + ' · ' + sim.aliveJoints;
  const prog = sim.phase === 'approach' ? clamp((cab.translation().x - sim.carX0) / (sim.wallX - sim.carX0), 0, 1) : 1;
  hud.bar.style.width = (prog * 100).toFixed(1) + '%';
}
const panel = document.getElementById('panel');
function buildPanel() {
  let html = '';
  for (const grp of SCHEMA) {
    html += `<h2>${grp.group}</h2>`;
    for (const [key, label, unit, min, max, step] of grp.items) html += `<label><span>${label}</span><input type="number" data-key="${key}" min="${min}" max="${max}" step="${step}" value="${settings[key]}"><span class="unit">${unit}</span></label>`;
  }
  html += `<div class="actions"><button id="btnApply" class="primary">Replay with values</button><button id="btnDefaults">Defaults</button></div>
    <div class="note">Replay reruns the rigid-body simulation with these values (fixed 120 Hz step, seeded). The defaults reproduce the baseline crash on every load.</div>`;
  panel.innerHTML = html;
  document.getElementById('btnApply').addEventListener('click', replay);
  document.getElementById('btnDefaults').addEventListener('click', () => { settings = { ...DEFAULTS }; fillPanel(); reset(settings); });
}
function fillPanel() { panel.querySelectorAll('input').forEach((inp) => { inp.value = settings[inp.dataset.key]; }); }
function readPanel() {
  const s = { ...settings };
  panel.querySelectorAll('input').forEach((inp) => {
    const key = inp.dataset.key, v = parseFloat(inp.value);
    if (Number.isFinite(v)) { let c = clamp(v, parseFloat(inp.min), parseFloat(inp.max)); if (parseFloat(inp.step) === 1) c = Math.round(c); s[key] = c; }
    inp.value = s[key];
  });
  return s;
}
function replay() { settings = readPanel(); reset(settings); }
document.getElementById('btnReplay').addEventListener('click', replay);
document.getElementById('btnSettings').addEventListener('click', () => panel.classList.toggle('open'));
window.addEventListener('keydown', (e) => { if ((e.key === 'r' || e.key === 'R') && !(e.target instanceof HTMLInputElement)) replay(); });

// Shadow frustum hugs the action: the wall plus every car part wherever it ended up, nothing else.
function updateShadowFrustum() {
  const wallX = sim.wallX;
  let minX = wallX - 6, maxX = wallX + 8, minZ = -6, maxZ = 6;
  for (const p of sim.parts) {
    if (!p.body) continue; const t = p.body.translation();
    minX = Math.min(minX, t.x - 3); maxX = Math.max(maxX, t.x + 3); minZ = Math.min(minZ, t.z - 2.5); maxZ = Math.max(maxZ, t.z + 2.5);
  }
  fitShadowToBox(minX, Math.min(maxX, minX + 70), Math.max(minZ, -12), Math.min(maxZ, 12), 3.6);
}

// ---------------------------------------------------------------- main loop: fixed 120 Hz physics, interpolation-free render sync
let last = performance.now(), acc = 0, hudLast = 0;
const dbSize = new THREE.Vector2();
function frame(now) {
  requestAnimationFrame(frame);
  const dtF = Math.min((now - last) / 1000, 0.1); last = now;
  acc += dtF; let n = 0;
  while (acc >= sim.dt && n < 4) { physicsStep(); acc -= sim.dt; n++; }
  if (n === 4) acc = 0;
  syncMeshes(dtF);
  updateContactShadows();
  renderer.getDrawingBufferSize(dbSize);
  const pScale = dbSize.y / (2 * Math.tan(THREE.MathUtils.degToRad(camera.fov) / 2));
  dust.update(dtF, pScale); sparks.update(dtF, pScale);
  updatePhase(); updateCamera(dtF, now); updateShadowFrustum();
  if (now - hudLast > 80) { updateHUD(); hudLast = now; } // DOM writes at ~12 Hz, not per frame
  renderer.render(scene, camera);
}
buildPanel();
reset(settings);
document.getElementById('loading').classList.add('hide');
requestAnimationFrame(frame);
</script>
