// ---------------------------------------------------------------- main loop: fixed 120 Hz physics on a scaled simulation clock, interpolation-free render sync
let last = performance.now(), acc = 0, hudLast = 0;
const MAX_STEPS = 8; // 2x still runs in real time down to 30 fps; past that the remainder is dropped rather than stepped coarser
const dbSize = new THREE.Vector2();
function frame(now) {
  requestAnimationFrame(frame);
  const dtF = Math.min((now - last) / 1000, 0.1); last = now;
  if (!play.paused) { // pause freezes physics, particles, skids and the sim clock; the world is left exactly as it is
    const dtS = dtF * play.speed; // simulation seconds this frame: the speed control scales the clock, the step stays 1/120 s
    acc += dtS; let n = 0;
    while (acc >= sim.dt && n < MAX_STEPS) { physicsStep(); acc -= sim.dt; n++; }
    if (n === MAX_STEPS) acc = 0;
    syncMeshes(dtS);
    updateContactShadows();
    renderer.getDrawingBufferSize(dbSize);
    const pScale = dbSize.y / (2 * Math.tan(THREE.MathUtils.degToRad(camera.fov) / 2)), dtP = Math.min(dtS, 0.05);
    dust.update(dtP, pScale); sparks.update(dtP, pScale);
    updatePhase(); updateShadowFrustum();
  }
  updateCamera(dtF, now); // the camera runs on wall-clock time: free look and view switches work while paused or in slow motion
  if (now - hudLast > 80) { updateHUD(); hudLast = now; } // DOM writes at ~12 Hz, not per frame
  renderer.render(scene, camera);
}

