// ---------------------------------------------------------------- playback state: lives outside `settings`, so it survives Replay / Apply / Defaults
const play = { paused: false, speed: 1, view: 'impact' };

// ---------------------------------------------------------------- camera rig: Impact (cinematic director), Top, Follow, Orbit (free look)
const cam = { pos: V3(), tgt: V3(), dPos: V3(), dTgt: V3(), shake: 0, glide: 0, orbitA: 0, orbitBase: 0, orbitR: 13, orbitH: 3.8 };
const controls = new OrbitControls(camera, renderer.domElement);
controls.enabled = false; controls.enableDamping = true; controls.maxPolarAngle = Math.PI / 2 - 0.03; controls.minDistance = 3; controls.maxDistance = 90;
controls.autoRotate = true; controls.autoRotateSpeed = 0.5; // gentle orbit whenever the user is not dragging
renderer.domElement.addEventListener('pointerdown', () => setView('orbit'), { capture: true });
renderer.domElement.addEventListener('wheel', () => setView('orbit'), { capture: true, passive: true });
const wc = V3(), estPos = V3(), estTgt = V3(), crashPos = V3(), crashTgt = V3(), carTgt = V3(), midPos = V3(), dirEst = V3(0.25, 0.28, 1).normalize();
function desiredTop() {
  const cabT = sim.partByName.get('cabin').body.translation();
  const vfov = THREE.MathUtils.degToRad(camera.fov), hfov = 2 * Math.atan(Math.tan(vfov / 2) * camera.aspect);
  let cx, cz, spanX;
  if (sim.phase === 'approach') { const x0 = cabT.x - 4, x1 = sim.wallX + 5; cx = (x0 + x1) / 2; cz = 0; spanX = x1 - x0; }
  else { wreckCenter(wc); cx = wc.x; cz = wc.z * 0.5; spanX = 26; }
  const H = clamp(Math.max(spanX / 2 / Math.tan(hfov / 2), (sim.wallW / 2 + 4) / Math.tan(vfov / 2)), 12, 60);
  cam.dPos.set(cx, H, cz + H * 0.03); cam.dTgt.set(cx, 0, cz); // tiny z offset keeps the up-vector valid and the track horizontal, car driving right
}
function desiredFollow() {
  const t = sim.partByName.get('cabin').body.translation();
  cam.dPos.set(t.x - 7.5, Math.max(t.y, 0.5) + 2.3, t.z + 3.0); cam.dTgt.set(t.x + 4, 0.7, t.z);
}
function computeDesired() { if (play.view === 'top') desiredTop(); else if (play.view === 'follow') desiredFollow(); else desiredImpact(); }
function setView(v) {
  const prev = play.view; play.view = v; setSeg(segView, 'view', v);
  if (v === 'orbit') { if (!controls.enabled) { controls.target.copy(cam.tgt); controls.enabled = true; } return; }
  if (prev === 'orbit') { cam.pos.copy(camera.position); cam.tgt.copy(controls.target); controls.enabled = false; }
  if (prev !== v) cam.glide = 1; // quick blend into the new view, then the view's own damping takes over
}
function desiredImpact() {
  const cabT = sim.partByName.get('cabin').body.translation(), wallX = sim.wallX;
  const hfov = 2 * Math.atan(Math.tan(THREE.MathUtils.degToRad(camera.fov) / 2) * camera.aspect);
  crashPos.set(wallX - 9, 2.8, 10.5); crashTgt.set(wallX - 3.2, 0.9, 0.2);
  if (sim.phase === 'approach') {
    // establishing three-quarter shot framing car + track + wall, swooping along a bezier to the crash camera
    const midX = (cabT.x + wallX) / 2, halfSpan = (wallX - cabT.x) / 2 + 5.5, D = halfSpan / Math.tan(hfov / 2);
    estTgt.set(midX, 1.0, 0); estPos.copy(estTgt).addScaledVector(dirEst, D);

